INSERT INTO litemall_issue (id,question,answer,add_time,update_time,deleted) VALUES
(1,'鲜花如何配送？多久可以送达？','同城订单由花艺师专车配送，下单后 2 小时内送达；外地订单使用顺丰冷链，一般次日达。节假日建议提前 1-2 天预订。','2025-06-01 10:00:00','2025-06-01 10:00:00',0),
(2,'运费怎么计算？','单笔订单满 99 元免运费，不满 99 元收取 12 元配送费；花篮、拱门等大型花艺按距离另行计算。','2025-06-01 10:00:00','2025-06-01 10:00:00',0),
(3,'收到的花不新鲜怎么办？','请在签收后 24 小时内拍照联系客服，经核实可免费重发或全额退款，花材新鲜度是我们的第一承诺。','2025-06-01 10:00:00','2025-06-01 10:00:00',0),
(4,'鲜花可以指定送达时间吗？','可以。下单时在备注中填写期望送达时间，花艺师会在配送前电话与您确认。','2025-06-01 10:00:00','2025-06-01 10:00:00',0),
(5,'如何让花期更长？','收到鲜花后斜剪根部 2cm，去掉浸水叶片，每日换水并清洗花瓶；避免阳光直射、空调风口与水果同放。','2025-06-01 10:00:00','2025-06-01 10:00:00',0);
INSERT INTO litemall_notice (id,title,content,admin_id,add_time,update_time,deleted) VALUES
(1,'鲜花配送与养护说明','同城鲜花 2 小时送达，满 99 元免运费；收到鲜花后请斜剪根部并每日换水，可有效延长花期。',0,'2025-06-01 10:00:00','2025-06-01 10:00:00',0),
(2,'节日预订提醒','情人节、母亲节等节日花材紧张，建议提前 1-2 天下单预订，可指定送达时间与祝福卡片内容。',0,'2025-06-01 10:00:00','2025-06-01 10:00:00',0);
